void prefix_sum_i64(const int64_t *in, int64_t *out, size_t n)
{
    int64_t s = 0;
    size_t i = 0;
    for (; i + 8 <= n; i += 8) {
        __builtin_prefetch(in + i + 64, 0, 0);
        int64_t a0 = in[i], a1 = in[i+1], a2 = in[i+2], a3 = in[i+3];
        int64_t a4 = in[i+4], a5 = in[i+5], a6 = in[i+6], a7 = in[i+7];
