        int64_t p2 = p1 + a2;
        int64_t p3 = p2 + a3;
        int64_t q1 = a4 + a5;
        int64_t q2 = q1 + a6;
        int64_t q3 = q2 + a7;
        int64_t base2 = s + p3;
        out[i]   = s + a0;
        out[i+1] = s + p1;
        out[i+2] = s + p2;
        out[i+3] = base2;
        out[i+4] = base2 + a4;
        out[i+5] = base2 + q1;
        out[i+6] = base2 + q2;
        out[i+7] = base2 + q3;
        s = base2 + q3;
    }
    for (; i < n; i++) {
        s += in[i];
        out[i] = s;
    }
