```c
#include <arm_neon.h>

float dot_f32(const float *a, const float *b, size_t n)
{
    double total = 0.0;
    size_t i = 0;
    const size_t BLK = 4096;
    while (i + BLK <= n) {
        float32x4_t s0 = vdupq_n_f32(0), s1 = s0, s2 = s0, s3 = s0,
                    s4 = s0, s5 = s0, s6 = s0, s7 = s0;
        size_t end = i + BLK;
        for (; i < end; i += 32) {
            s0 = vfmaq_f32(s0, vld1q_f32(a + i),      vld1q_f32(b + i));
            s1 = vfmaq_f32(s1, vld1q_f32(a + i + 4),  vld1q_f32(b + i + 4));
            s2 = vfmaq_f32(s2, vld1q_f32(a + i + 8),  vld1q_f32(b + i + 8));
            s3 = vfmaq_f32(s3, vld1q_f32(a + i + 12), vld1q_f32(b + i + 12));
            s4 = vfmaq_f32(s4, vld1q_f32(a + i + 16), vld1q_f32(b + i + 16));
            s5 = vfmaq_f32(s5, vld1q_f32(a + i + 20), vld1q_f32(b + i + 20));
            s6 = vfmaq_f32(s6, vld1q_f32(a + i + 24), vld1q_f32(b + i + 24));
            s7 = vfmaq_f32(s7, vld1q_f32(a + i + 28), vld1q_f32(b + i + 28));
        }
        s0 = vaddq_f32(s0, s1);
        s2 = vaddq_f32(s2, s3);
        s4 = vaddq_f32(s4, s5);
        s6 = vaddq_f32(s6, s7);
        s0 = vaddq_f32(s0, s2);
        s4 = vaddq_f32(s4, s6);
        s0 = vaddq_f32(s0, s4);
        total += (double)vaddvq_f32(s0);
    }
    {
        float32x4_t s = vdupq_n_f32(0);
        for (; i + 4 <= n; i += 4)
            s = vfmaq_f32(s, vld1q_f32(a + i), vld1q_f32(b + i));
        total += (double)vaddvq_f32(s);
    }
    for (; i < n; i++)
        total += (double)a[i] * (double)b[i];
    return (float)total;
}
```
