#include <arm_neon.h>

float dot_f32(const float *a, const float *b, size_t n)
{
    double total = 0.0;
    size_t i = 0;
    const size_t CH = 8192;
    while (i + 32 <= n) {
        size_t rem = n - i;
        size_t len = rem < CH ? rem : CH;
        len &= ~(size_t)31;
        const float *pa = a + i;
        const float *pb = b + i;
        float32x4_t s0 = vdupq_n_f32(0), s1 = s0, s2 = s0, s3 = s0,
                    s4 = s0, s5 = s0, s6 = s0, s7 = s0;
        for (size_t j = 0; j < len; j += 32) {
            s0 = vfmaq_f32(s0, vld1q_f32(pa + j),      vld1q_f32(pb + j));
            s1 = vfmaq_f32(s1, vld1q_f32(pa + j + 4),  vld1q_f32(pb + j + 4));
            s2 = vfmaq_f32(s2, vld1q_f32(pa + j + 8),  vld1q_f32(pb + j + 8));
            s3 = vfmaq_f32(s3, vld1q_f32(pa + j + 12), vld1q_f32(pb + j + 12));
            s4 = vfmaq_f32(s4, vld1q_f32(pa + j + 16), vld1q_f32(pb + j + 16));
            s5 = vfmaq_f32(s5, vld1q_f32(pa + j + 20), vld1q_f32(pb + j + 20));
            s6 = vfmaq_f32(s6, vld1q_f32(pa + j + 24), vld1q_f32(pb + j + 24));
            s7 = vfmaq_f32(s7, vld1q_f32(pa + j + 28), vld1q_f32(pb + j + 28));
        }
        s0 = vaddq_f32(vaddq_f32(s0, s1), vaddq_f32(s2, s3));
        s4 = vaddq_f32(vaddq_f32(s4, s5), vaddq_f32(s6, s7));
        s0 = vaddq_f32(s0, s4);
        total += (double)vaddvq_f32(s0);
        i += len;
    }
    for (; i < n; i++)
        total += (double)(a[i] * b[i]);
    return (float)total;
