void byte_histogram(const uint8_t *data, size_t n, uint64_t counts[256])
{
    uint64_t t[4][256];
    memset(t, 0, sizeof(t));
    uint8_t cur = 0;
    uint64_t run = 0;
    uint8x16_t pat = vdupq_n_u8(0);
    size_t i = 0;
    for (; i + 64 <= n; i += 64) {
        const uint8_t *p = data + i;
        uint8x16_t a = vld1q_u8(p);
        uint8x16_t b = vld1q_u8(p + 16);
        uint8x16_t c = vld1q_u8(p + 32);
        uint8x16_t d = vld1q_u8(p + 48);
        uint8x16_t x = vorrq_u8(vorrq_u8(veorq_u8(a, pat), veorq_u8(b, pat)),
                                vorrq_u8(veorq_u8(c, pat), veorq_u8(d, pat)));
        if (vmaxvq_u8(x) == 0) {
            run += 64;
        } else {
            t[0][cur] += run;
            run = 0;
            for (int j = 0; j < 64; j += 4) {
                t[0][p[j]]++;
                t[1][p[j + 1]]++;
                t[2][p[j + 2]]++;
                t[3][p[j + 3]]++;
            }
            cur = p[63];
            pat = vdupq_n_u8(cur);
        }
    }
    t[0][cur] += run;
    for (; i < n; i++)
        t[0][data[i]]++;
    for (int b = 0; b < 256; b++)
        counts[b] = t[0][b] + t[1][b] + t[2][b] + t[3][b];
}
