I used the Lucy_Hedgehog prime-counting algorithm instead of a sieve. It runs in about O(n^¾) time and needs only about 2·√n counters, roughly 14k entries for n = 50M. That is far below the 4 MiB limit, and I expect it to take well under the time of a straightforward sieve. I could not compile or run it, so this is untested.

- **State:** `small[i]` counts the numbers up to `i` that survive sieving so far, and `large[i]` does the same for `n/i`.
- **Update order:** the `large` loop reads `large[i*p]` and `small[(n/i)/p]` before they are overwritten. The `small` loop runs from high to low so `small[i/p]` is still the old value.
- **Types:** for n below 2^32 it uses 32-bit counters and divisions, which are faster on AArch64. Larger n uses 64-bit.
- **Edge cases:** n < 2 returns 0. If `malloc` fails it returns 0.

<answer>
```c
#include <stdint.h>
#include <stdlib.h>
#include <math.h>

#define LUCY(NAME, T)                                                     \
static uint64_t NAME(T n, T r) {                                          \
    T *small = (T *)malloc(sizeof(T) * (2 * (size_t)r + 2));              \
    if (!small) return 0;                                                 \
    T *large = small + r + 1;                                             \
    for (T i = 0; i <= r; i++) small[i] = i ? i - 1 : 0;                  \
    for (T i = 1; i <= r; i++) large[i] = n / i - 1;                      \
    for (T p = 2; p <= r; p++) {                                          \
        if (small[p] == small[p - 1]) continue;                           \
        T pc = small[p - 1];                                              \
        T p2 = p * p;                                                     \
        T lim = n / p2; if (lim > r) lim = r;                             \
        for (T i = 1; i <= lim; i++) {                                    \
            T d = i * p;                                                  \
            T val = (d <= r) ? large[d] : small[(n / i) / p];             \
            large[i] -= val - pc;                                         \
        }                                                                 \
        for (T i = r; i >= p2; i--) {                                     \
            small[i] -= small[i / p] - pc;                                \
        }                                                                 \
    }                                                                     \
    uint64_t res = large[1];                                              \
    free(small);                                                          \
    return res;                                                           \
}

LUCY(lucy32, uint32_t)
LUCY(lucy64, uint64_t)

uint64_t count_primes(uint64_t n) {
    if (n < 2) return 0;
    uint64_t r = (uint64_t)sqrt((double)n);
    while (r * r > n) r--;
    while ((r + 1) * (r + 1) <= n) r++;
    if (n < 4294967296ULL) return lucy32((uint32_t)n, (uint32_t)r);
    return lucy64(n, r);
}
