This uses the Lucy_Hedgehog prime-counting method, which runs in roughly O(n^{3/4}) time. For n ≈ 50M that is on the order of a million simple operations, far fewer than a sieve needs, so it should be many times faster than a straightforward sieve. I have not compiled or run it.

- **Memory:** two arrays of about √n 64-bit entries each. That is ~113 KB at n = 50M, well under 4 MiB. The limit would be exceeded only for n above roughly 10^11, which is outside the benchmark.
- **Tiny inputs:** `n < 2` returns 0 immediately. For `n = 2` and `n = 3` the sieve loop is trivially correct.
- **Square root:** the integer square root starts from `sqrt` and is corrected up or down, so it is exact.
- **Update order:** the `hi` array is updated in ascending `i` and the `lo` array in descending `i`. Each update therefore reads values from the previous round, as the algorithm requires.

<answer>
```c
#include <stdint.h>
#include <stdlib.h>
#include <math.h>

uint64_t count_primes(uint64_t n)
{
    if (n < 2) return 0;
    uint64_t r = (uint64_t)sqrt((double)n);
    while (r * r > n) r--;
    while ((r + 1) * (r + 1) <= n) r++;

    uint64_t *lo = (uint64_t *)malloc((r + 2) * sizeof(uint64_t));
    uint64_t *hi = (uint64_t *)malloc((r + 2) * sizeof(uint64_t));
    if (!lo || !hi) { free(lo); free(hi); return 0; }

    lo[0] = 0;
    for (uint64_t i = 1; i <= r; i++) {
        lo[i] = i - 1;
        hi[i] = n / i - 1;
    }

    for (uint64_t p = 2; p <= r; p++) {
        if (lo[p] == lo[p - 1]) continue;
        uint64_t pc = lo[p - 1];
        uint64_t p2 = p * p;
        uint64_t lim = n / p2;
        if (lim > r) lim = r;
        for (uint64_t i = 1; i <= lim; i++) {
            uint64_t d = i * p;
            uint64_t v = (d <= r) ? hi[d] : lo[n / d];
            hi[i] -= v - pc;
        }
        for (uint64_t i = r; i >= p2; i--) {
            lo[i] -= lo[i / p] - pc;
        }
    }
    uint64_t res = hi[1];
    free(lo);
    free(hi);
    return res;
}
```
