This is an LSD radix sort with 11-bit digits (11+11+10 bits, so three passes), using one n-sized scratch buffer. I have not compiled or run it.

- **Histograms:** a single read pass builds all three histograms at once, then each is turned into prefix offsets.
- **Skipped passes:** a pass is skipped when every element falls in one bucket, which is common with many duplicates.
- **Ping-pong:** passes alternate between `a` and the scratch buffer, with a final `memcpy` back to `a` if the result ended up in the scratch buffer.
- **Memory:** the scratch buffer is 16 MiB for 4M elements and the histograms are 24 KB on the stack, which stays under the 20 MiB limit.
- **Small inputs:** inputs of 32 elements or fewer use insertion sort. If `malloc` fails, it falls back to `qsort`.

<answer>
```c
#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>

static int k_cmp_u32_unused(const void *x, const void *y) {
    uint32_t a = *(const uint32_t *)x, b = *(const uint32_t *)y;
    return (a > b) - (a < b);
}

void sort_u32(uint32_t *a, size_t n) {
    if (n < 2) return;
    if (n <= 32) {
        for (size_t i = 1; i < n; i++) {
            uint32_t v = a[i];
            size_t j = i;
            while (j > 0 && a[j - 1] > v) {
                a[j] = a[j - 1];
                j--;
            }
            a[j] = v;
        }
        return;
    }
    uint32_t *buf = (uint32_t *)malloc(n * sizeof(uint32_t));
    if (!buf) {
        qsort(a, n, sizeof(uint32_t), k_cmp_u32_unused);
        return;
    }
    uint32_t c[3][2048];
    memset(c, 0, sizeof(c));
    for (size_t i = 0; i < n; i++) {
        uint32_t v = a[i];
        c[0][v & 2047]++;
        c[1][(v >> 11) & 2047]++;
        c[2][v >> 22]++;
    }
    uint32_t *src = a, *dst = buf;
    uint32_t first = a[0];
    for (int p = 0; p < 3; p++) {
        int sh = p * 11;
        uint32_t mask = p == 2 ? 1023u : 2047u;
        uint32_t *cp = c[p];
        if (cp[(first >> sh) & mask] == n) continue;
        uint32_t sum = 0;
        for (int k = 0; k < 2048; k++) {
            uint32_t t = cp[k];
            cp[k] = sum;
            sum += t;
        }
        for (size_t i = 0; i < n; i++) {
            uint32_t v = src[i];
            dst[cp[(v >> sh) & mask]++] = v;
        }
        uint32_t *t = src; src = dst; dst = t;
    }
    if (src != a) memcpy(a, src, n * sizeof(uint32_t));
    free(buf);
}
```
