```c
#include <arm_neon.h>

static void matmul_fallback(const float *A, const float *B, float *C, size_t n)
{
    for (size_t i = 0; i < n; i++) {
        float *c = C + i * n;
        for (size_t j = 0; j < n; j++) c[j] = 0.0f;
        for (size_t k = 0; k < n; k++) {
            float a = A[i * n + k];
            const float *b = B + k * n;
            for (size_t j = 0; j < n; j++) c[j] += a * b[j];
        }
    }
}

void matmul_f32(const float *A, const float *B, float *C, size_t n)
{
    if (n == 0) return;
    float *Bp = NULL;
    if ((n & 7) == 0 && n <= 100000) Bp = (float *)malloc(n * 8 * sizeof(float));
    if (!Bp) {
        matmul_fallback(A, B, C, n);
        return;
    }
    for (size_t j = 0; j < n; j += 8) {
        /* pack B panel */
        for (size_t k = 0; k < n; k++) {
            const float *src = B + k * n + j;
            float *dst = Bp + k * 8;
            vst1q_f32(dst, vld1q_f32(src));
            vst1q_f32(dst + 4, vld1q_f32(src + 4));
        }
        for (size_t i = 0; i < n; i += 8) {
            float32x4_t acc0[8], acc1[8];
            #pragma GCC unroll 8
            for (int r = 0; r < 8; r++) {
                acc0[r] = vdupq_n_f32(0.0f);
                acc1[r] = vdupq_n_f32(0.0f);
            }
            const float *a0 = A + i * n;
            for (size_t k = 0; k < n; k += 4) {
                float32x4_t av[8];
                #pragma GCC unroll 8
                for (int r = 0; r < 8; r++) av[r] = vld1q_f32(a0 + (size_t)r * n + k);
                const float *bp = Bp + k * 8;
#define STEP(l) { \
    float32x4_t b0 = vld1q_f32(bp + (l) * 8); \
    float32x4_t b1 = vld1q_f32(bp + (l) * 8 + 4); \
    _Pragma("GCC unroll 8") \
    for (int r = 0; r < 8; r++) { \
        acc0[r] = vfmaq_laneq_f32(acc0[r], b0, av[r], l); \
        acc1[r] = vfmaq_laneq_f32(acc1[r], b1, av[r], l); \
    } }
                STEP(0)
                STEP(1)
                STEP(2)
                STEP(3)
#undef STEP
            }
            #pragma GCC unroll 8
            for (int r = 0; r < 8; r++) {
                float *c = C + (i + r) * n + j;
                vst1q_f32(c, acc0[r]);
                vst1q_f32(c + 4, acc1[r]);
