This is a NEON implementation that I have not compiled or run, so it is untested. It packs panels of A and B and runs an 8×12 register-blocked micro-kernel.

- **Blocking:** columns are processed in chunks of 384 and the k dimension in chunks of 192. For n = 384 that is a single column chunk and two even k passes. The packed B buffer is about 295 KB, well under the 4 MiB limit, and the packed A panel (6 KB) lives on the stack.
- **Packing:** A is packed in blocks of 8 rows as `[k][8]` and B in panels of 12 columns as `[k][12]`. Both are zero-padded at the edges, so the kernel never needs bounds checks.
- **Micro-kernel:** it holds 24 accumulators plus 3 B vectors and 2 A vectors, 29 of the 32 NEON registers. Each k step does 24 `vfmaq_laneq_f32` FMAs.
- **Edges and accumulation:** full 8×12 tiles are written straight to C. Partial tiles go through a temporary 8×12 buffer and are copied or added into C. The first k chunk overwrites C and later chunks add to it, so C need not be zeroed beforehand.
- **Small cases:** n = 0 returns immediately, and tiny n works through the zero-padded edge path.

<answer>
```c
#include <arm_neon.h>

#define MM_KC 192
#define MM_NC 384
#define MM_MR 8
#define MM_NR 12

static inline void mm_kern(int kc, const float *a, const float *b, float *c,
                           size_t ldc, int accum)
{
    float32x4_t acc[8][3];
    for (int i = 0; i < 8; i++)
        for (int j = 0; j < 3; j++)
            acc[i][j] = vdupq_n_f32(0.f);
    for (int k = 0; k < kc; k++) {
        float32x4_t b0 = vld1q_f32(b);
        float32x4_t b1 = vld1q_f32(b + 4);
        float32x4_t b2 = vld1q_f32(b + 8);
        float32x4_t a0 = vld1q_f32(a);
        float32x4_t a1 = vld1q_f32(a + 4);
#define ROW(i, av, lane)                                         \
        acc[i][0] = vfmaq_laneq_f32(acc[i][0], b0, av, lane);    \
        acc[i][1] = vfmaq_laneq_f32(acc[i][1], b1, av, lane);    \
        acc[i][2] = vfmaq_laneq_f32(acc[i][2], b2, av, lane);
        ROW(0, a0, 0) ROW(1, a0, 1) ROW(2, a0, 2) ROW(3, a0, 3)
        ROW(4, a1, 0) ROW(5, a1, 1) ROW(6, a1, 2) ROW(7, a1, 3)
#undef ROW
        a += 8;
        b += 12;
    }
    for (int i = 0; i < 8; i++) {
        float *cr = c + (size_t)i * ldc;
        for (int j = 0; j < 3; j++) {
            float32x4_t v = acc[i][j];
            if (accum) v = vaddq_f32(v, vld1q_f32(cr + 4 * j));
            vst1q_f32(cr + 4 * j, v);
        }
    }
}

void matmul_f32(const float *A, const float *B, float *C, size_t n)
{
    if (n == 0) return;
    float *bp = (float *)malloc(sizeof(float) * MM_KC * (MM_NC + MM_NR));
    if (!bp) return;
    float ap[MM_KC * MM_MR] __attribute__((aligned(16)));
    float tmp[MM_MR * MM_NR] __attribute__((aligned(16)));

    for (size_t jc = 0; jc < n; jc += MM_NC) {
        size_t nc = n - jc < MM_NC ? n - jc : MM_NC;
        size_t npan = (nc + MM_NR - 1) / MM_NR;
        for (size_t pc = 0; pc < n; pc += MM_KC) {
            size_t kc = n - pc < MM_KC ? n - pc : MM_KC;
            int accum = pc > 0;
            /* pack B */
            for (size_t p = 0; p < npan; p++) {
                size_t j0 = jc + p * MM_NR;
                size_t w = (j0 < jc + nc) ? (jc + nc - j0) : 0;
                if (w > MM_NR) w = MM_NR;
                float *dst = bp + p * kc * MM_NR;
                for (size_t k = 0; k < kc; k++) {
                    const float *src = B + (pc + k) * n + j0;
                    size_t j = 0;
                    for (; j < w; j++) dst[j] = src[j];
                    for (; j < MM_NR; j++) dst[j] = 0.f;
                    dst += MM_NR;
                }
            }
            for (size_t ic = 0; ic < n; ic += MM_MR) {
                size_t mr = n - ic < MM_MR ? n - ic : MM_MR;
                /* pack A */
                for (size_t k = 0; k < kc; k++) {
                    size_t r = 0;
                    for (; r < mr; r++)
                        ap[k * 8 + r] = A[(ic + r) * n + pc + k];
                    for (; r < 8; r++) ap[k * 8 + r] = 0.f;
                }
                for (size_t p = 0; p < npan; p++) {
                    size_t j0 = jc + p * MM_NR;
                    size_t w = jc + nc - j0;
                    if (w > MM_NR) w = MM_NR;
                    const float *bpan = bp + p * kc * MM_NR;
                    if (mr == MM_MR && w == MM_NR) {
                        mm_kern((int)kc, ap, bpan, C + ic * n + j0, n, accum);
                    } else {
                        mm_kern((int)kc, ap, bpan, tmp, MM_NR, 0);
                        for (size_t i = 0; i < mr; i++) {
                            float *cr = C + (ic + i) * n + j0;
                            for (size_t j = 0; j < w; j++) {
                                if (accum) cr[j] += tmp[i * MM_NR + j];
                                else cr[j] = tmp[i * MM_NR + j];
                            }
                        }
                    }
                }
            }
        }
    }
    free(bp);
}
