#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>

static void k_insertion_dummy_unused(void) {}

static void ins_sort(uint32_t *a, size_t n)
{
    for (size_t i = 1; i < n; i++) {
        uint32_t v = a[i];
        size_t j = i;
        while (j > 0 && a[j - 1] > v) {
            a[j] = a[j - 1];
            j--;
        }
        a[j] = v;
    }
}

static void qsort_u32(uint32_t *a, size_t n)
{
    while (n > 32) {
        uint32_t x = a[0], y = a[n / 2], z = a[n - 1];
        uint32_t p;
        if (x < y) p = y < z ? y : (x < z ? z : x);
        else p = x < z ? x : (y < z ? z : y);
        size_t i = 0, j = n - 1;
        for (;;) {
            while (a[i] < p) i++;
            while (a[j] > p) j--;
            if (i >= j) break;
            uint32_t t = a[i]; a[i] = a[j]; a[j] = t;
            i++; j--;
        }
        /* partition: [0..j], [j+1..n-1] when i>=j; handle i==j case */
        size_t left = j + 1;
        if (i == j) { /* a[j]==p, belongs to left side is fine */ left = j + 1; }
        if (left == 0 || left == n) { left = n / 2; /* safety, should not happen */
            ins_sort(a, n); return; }
        if (left < n - left) {
            qsort_u32(a, left);
            a += left; n -= left;
        } else {
            qsort_u32(a + left, n - left);
            n = left;
        }
    }
    ins_sort(a, n);
}

void sort_u32(uint32_t *a, size_t n)
{
    if (n <= 64) {
        ins_sort(a, n);
        return;
    }
    uint32_t *tmp = NULL;
    if (n <= (size_t)(19u << 20) / 4)
        tmp = (uint32_t *)malloc(n * sizeof(uint32_t));
    if (!tmp) {
        qsort_u32(a, n);
        return;
    }
    static uint32_t h[3][2048];
    memset(h, 0, sizeof(h));
    for (size_t i = 0; i < n; i++) {
        uint32_t v = a[i];
        h[0][v & 2047]++;
        h[1][(v >> 11) & 2047]++;
        h[2][v >> 22]++;
    }
    uint32_t *src = a, *dst = tmp;
    for (int p = 0; p < 3; p++) {
        uint32_t *c = h[p];
        int shift = p * 11;
        uint32_t mask = p == 2 ? 1023u : 2047u;
        /* skip if single bucket */
        uint32_t first = (src[0] >> shift) & mask;
        if (c[first] == n) continue;
        uint32_t sum = 0;
        for (int k = 0; k < 2048; k++) {
            uint32_t t = c[k];
            c[k] = sum;
            sum += t;
        }
        size_t i = 0;
        for (; i + 4 <= n; i += 4) {
            uint32_t v0 = src[i], v1 = src[i + 1], v2 = src[i + 2], v3 = src[i + 3];
            dst[c[(v0 >> shift) & mask]++] = v0;
            dst[c[(v1 >> shift) & mask]++] = v1;
            dst[c[(v2 >> shift) & mask]++] = v2;
            dst[c[(v3 >> shift) & mask]++] = v3;
        }
        for (; i < n; i++) {
            uint32_t v = src[i];
            dst[c[(v >> shift) & mask]++] = v;
        }
        uint32_t *t = src; src = dst; dst = t;
    }
    if (src != a)
        memcpy(a, src, n * sizeof(uint32_t));
    free(tmp);
}
