#include <arm_neon.h>

static inline uint8x16_t k_build(const unsigned char *p) {
    uint8x16_t t0 = vld1q_u8(p);
    uint8x16_t t1 = vld1q_u8(p + 1);
    uint8x16_t t2 = vld1q_u8(p + 2);
    uint8x16_t t3 = vld1q_u8(p + 3);
    uint8x16_t x = vsliq_n_u8(t2, t3, 2);
    x = vsliq_n_u8(t1, x, 2);
    x = vsliq_n_u8(t0, x, 2);
    return x;
}

uint64_t count_substr(const char *text, size_t n, const char *pat, size_t m) {
    if (m > n || m == 0) return 0;
    const unsigned char *t = (const unsigned char *)text;
    const unsigned char *pp = (const unsigned char *)pat;
    uint64_t cnt = 0;
    if (m == 12) {
        size_t i = 0;
        uint8_t w[3];
        for (int g = 0; g < 3; g++) {
            w[g] = (uint8_t)((pp[4*g] & 3) | ((pp[4*g+1] & 3) << 2) |
                             ((pp[4*g+2] & 3) << 4) | ((pp[4*g+3] & 3) << 6));
        }
        if (n >= 35) {
            uint8x16_t P0 = vdupq_n_u8(w[0]);
            uint8x16_t P1 = vdupq_n_u8(w[1]);
            uint8x16_t P2 = vdupq_n_u8(w[2]);
            uint8x16_t A = k_build(t);
            uint8x16_t acc = vdupq_n_u8(0);
            unsigned it = 0;
            while (i + 35 <= n) {
                uint8x16_t B = k_build(t + i + 16);
                uint8x16_t e4 = vextq_u8(A, B, 4);
                uint8x16_t e8 = vextq_u8(A, B, 8);
                uint8x16_t mk = vandq_u8(vandq_u8(vceqq_u8(A, P0), vceqq_u8(e4, P1)),
                                         vceqq_u8(e8, P2));
                acc = vsubq_u8(acc, mk);
                A = B;
                i += 16;
                if (++it == 255) {
                    cnt += vaddlvq_u8(acc);
                    acc = vdupq_n_u8(0);
                    it = 0;
                }
            }
            cnt += vaddlvq_u8(acc);
        }
        for (; i + m <= n; i++) {
            if (memcmp(t + i, pat, 12) == 0) cnt++;
        }
        return cnt;
    }
    if (m <= 32) {
        uint64_t p = 0;
        for (size_t j = 0; j < m; j++) p = (p << 2) | (pp[j] & 3);
        uint64_t mask = (m == 32) ? ~0ULL : ((1ULL << (2 * m)) - 1);
        uint64_t win = 0;
        size_t i = 0;
        for (; i + 1 < m; i++) win = (win << 2) | (t[i] & 3);
        for (; i < n; i++) {
            win = (win << 2) | (t[i] & 3);
            cnt += ((win & mask) == p);
        }
        return cnt;
    }
    for (size_t i = 0; i + m <= n; i++) {
        if (t[i] == pp[0] && memcmp(t + i, pat, m) == 0) cnt++;
    }
    return cnt;
}
