#include <arm_neon.h>

static inline void tr4x4(const float *restrict in, float *restrict out,
                         size_t rows, size_t cols, size_t i, size_t j)
{
    const float *p = in + i * cols + j;
    float32x4_t a0 = vld1q_f32(p);
    float32x4_t a1 = vld1q_f32(p + cols);
    float32x4_t a2 = vld1q_f32(p + 2 * cols);
    float32x4_t a3 = vld1q_f32(p + 3 * cols);
    float32x4_t t0 = vtrn1q_f32(a0, a1);
    float32x4_t t1 = vtrn2q_f32(a0, a1);
    float32x4_t t2 = vtrn1q_f32(a2, a3);
    float32x4_t t3 = vtrn2q_f32(a2, a3);
    float32x4_t c0 = vreinterpretq_f32_f64(vtrn1q_f64(vreinterpretq_f64_f32(t0), vreinterpretq_f64_f32(t2)));
    float32x4_t c1 = vreinterpretq_f32_f64(vtrn1q_f64(vreinterpretq_f64_f32(t1), vreinterpretq_f64_f32(t3)));
    float32x4_t c2 = vreinterpretq_f32_f64(vtrn2q_f64(vreinterpretq_f64_f32(t0), vreinterpretq_f64_f32(t2)));
    float32x4_t c3 = vreinterpretq_f32_f64(vtrn2q_f64(vreinterpretq_f64_f32(t1), vreinterpretq_f64_f32(t3)));
    float *q = out + j * rows + i;
    vst1q_f32(q, c0);
    vst1q_f32(q + rows, c1);
    vst1q_f32(q + 2 * rows, c2);
    vst1q_f32(q + 3 * rows, c3);
}

void transpose_f32(const float *in, float *out, size_t rows, size_t cols)
{
    size_t r16 = rows & ~(size_t)15;
    size_t c16 = cols & ~(size_t)15;

    for (size_t i0 = 0; i0 < r16; i0 += 16) {
        for (size_t j0 = 0; j0 < c16; j0 += 16) {
            for (size_t jj = 0; jj < 16; jj += 4)
                for (size_t ii = 0; ii < 16; ii += 4)
                    tr4x4(in, out, rows, cols, i0 + ii, j0 + jj);
        }
    }
    /* column remainder, all rows */
    if (c16 < cols) {
        for (size_t i = 0; i < rows; i++)
            for (size_t j = c16; j < cols; j++)
                out[j * rows + i] = in[i * cols + j];
    }
    /* row remainder, columns handled by vector path */
    if (r16 < rows) {
        for (size_t i = r16; i < rows; i++)
            for (size_t j = 0; j < c16; j++)
                out[j * rows + i] = in[i * cols + j];
    }
}
