    float32x4_t r1 = vld1q_f32(in + ldi);
    float32x4_t r2 = vld1q_f32(in + 2 * ldi);
    float32x4_t r3 = vld1q_f32(in + 3 * ldi);
    float32x4_t t0 = vtrn1q_f32(r0, r1);
    float32x4_t t1 = vtrn2q_f32(r0, r1);
    float32x4_t t2 = vtrn1q_f32(r2, r3);
    float32x4_t t3 = vtrn2q_f32(r2, r3);
    float64x2_t u0 = vreinterpretq_f64_f32(t0);
    float64x2_t u1 = vreinterpretq_f64_f32(t1);
    float64x2_t u2 = vreinterpretq_f64_f32(t2);
    float64x2_t u3 = vreinterpretq_f64_f32(t3);
    vst1q_f32(out,           vreinterpretq_f32_f64(vtrn1q_f64(u0, u2)));
    vst1q_f32(out + ldo,     vreinterpretq_f32_f64(vtrn1q_f64(u1, u3)));
    vst1q_f32(out + 2 * ldo, vreinterpretq_f32_f64(vtrn2q_f64(u0, u2)));
    vst1q_f32(out + 3 * ldo, vreinterpretq_f32_f64(vtrn2q_f64(u1, u3)));
}

void transpose_f32(const float *in, float *out, size_t rows, size_t cols)
{
    size_t rm = rows & ~(size_t)15;
    size_t cm = cols & ~(size_t)15;

    for (size_t ib = 0; ib < rm; ib += 16) {
        for (size_t jb = 0; jb < cm; jb += 16) {
            if (jb + 16 < cm) {
                for (size_t r = 0; r < 16; r++)
                    __builtin_prefetch(in + (ib + r) * cols + jb + 16);
