            for (size_t jj = 0; jj < 16; jj += 4) {
                for (size_t ii = 0; ii < 16; ii += 4) {
                    tr4(in + (ib + ii) * cols + jb + jj, cols,
                        out + (jb + jj) * rows + ib + ii, rows);
