            }
        }
    }
    /* right edge columns, all rows */
    if (cm < cols) {
        for (size_t i = 0; i < rows; i++)
            for (size_t j = cm; j < cols; j++)
                out[j * rows + i] = in[i * cols + j];
    }
    /* bottom edge rows, main columns */
    if (rm < rows) {
        for (size_t i = rm; i < rows; i++)
            for (size_t j = 0; j < cm; j++)
                out[j * rows + i] = in[i * cols + j];
    }
