#include <arm_neon.h>

static inline void k_unused_dummy_never(void) {}

static inline void cs_block(const uint8_t *p, uint64_t L[4]) {
    static const uint8_t wt[16] = {1,2,4,8,16,32,64,128,1,2,4,8,16,32,64,128};
    uint8x16_t w = vld1q_u8(wt);
    uint8x16_t one = vdupq_n_u8(1);
    uint8x16_t two = vdupq_n_u8(2);
    uint8x16_t v0 = vld1q_u8(p);
    uint8x16_t v1 = vld1q_u8(p + 16);
    uint8x16_t v2 = vld1q_u8(p + 32);
    uint8x16_t v3 = vld1q_u8(p + 48);

    uint8x16_t a0 = vandq_u8(vtstq_u8(v0, one), w);
    uint8x16_t a1 = vandq_u8(vtstq_u8(v1, one), w);
    uint8x16_t a2 = vandq_u8(vtstq_u8(v2, one), w);
    uint8x16_t a3 = vandq_u8(vtstq_u8(v3, one), w);
    uint8x16_t x = vpaddq_u8(a0, a1);
    uint8x16_t y = vpaddq_u8(a2, a3);
    x = vpaddq_u8(x, y);
    x = vpaddq_u8(x, x);
    uint64_t p0 = vgetq_lane_u64(vreinterpretq_u64_u8(x), 0);

    uint8x16_t b0 = vandq_u8(vtstq_u8(v0, two), w);
    uint8x16_t b1 = vandq_u8(vtstq_u8(v1, two), w);
    uint8x16_t b2 = vandq_u8(vtstq_u8(v2, two), w);
    uint8x16_t b3 = vandq_u8(vtstq_u8(v3, two), w);
    x = vpaddq_u8(b0, b1);
    y = vpaddq_u8(b2, b3);
    x = vpaddq_u8(x, y);
    x = vpaddq_u8(x, x);
    uint64_t p1 = vgetq_lane_u64(vreinterpretq_u64_u8(x), 0);

    L[0] = ~(p0 | p1);
    L[1] = p0 & ~p1;
    L[2] = ~p0 & p1;
    L[3] = p0 & p1;
}

uint64_t count_substr(const char *text, size_t n, const char *pat, size_t m) {
    if (m > n || m == 0) return 0;
    const uint8_t *t = (const uint8_t *)text;
    unsigned cj[64];
    for (size_t j = 0; j < m; j++) cj[j] = (unsigned)pat[j] & 3u;

    uint64_t count = 0;
    size_t k = 0;
    if (n >= 128) {
        uint64_t A[4], B[4];
        uint64_t *cur = A, *nxt = B;
        cs_block(t, cur);
        while ((k + 2) * 64 <= n) {
            cs_block(t + (k + 1) * 64, nxt);
            uint64_t acc = cur[cj[0]];
            for (size_t j = 1; j < m; j++) {
                unsigned c = cj[j];
                acc &= (cur[c] >> j) | (nxt[c] << (64 - j));
            }
            count += (uint64_t)__builtin_popcountll(acc);
            uint64_t *tmp = cur; cur = nxt; nxt = tmp;
            k++;
        }
    }
    size_t start = k * 64;
    for (size_t p = start; p + m <= n; p++) {
        if (t[p] == (uint8_t)pat[0] && memcmp(t + p, pat, m) == 0) count++;
    }
    return count;
}
