        float32x4_t v1 = vld1q_f32(t + 4);
        float32x4_t v2 = vld1q_f32(t + 8);
        float32x4_t v3 = vld1q_f32(t + 12);
        vst1q_f32(o, v0);
        vst1q_f32(o + 4, v1);
        vst1q_f32(o + 8, v2);
        vst1q_f32(o + 12, v3);
    }
}

void transpose_f32(const float *in, float *out, size_t rows, size_t cols)
{
    size_t r16 = rows & ~(size_t)15;
    size_t c16 = cols & ~(size_t)15;
    const size_t B = 64;

    for (size_t I = 0; I < r16; I += B) {
        size_t iend = I + B < r16 ? I + B : r16;
        for (size_t J = 0; J < c16; J += B) {
            size_t jend = J + B < c16 ? J + B : c16;
            for (size_t i = I; i < iend; i += 16) {
                for (size_t j = J; j < jend; j += 16) {
                    tr_tile16(in + i * cols + j, cols, out + j * rows + i, rows);
                }
            }
        }
    }
    /* leftover columns (all rows) */
    if (c16 < cols) {
        for (size_t i = 0; i < rows; i++)
            for (size_t j = c16; j < cols; j++)
                out[j * rows + i] = in[i * cols + j];
    }
    /* leftover rows (columns < c16) */
    if (r16 < rows) {
        for (size_t i = r16; i < rows; i++)
            for (size_t j = 0; j < c16; j++)
                out[j * rows + i] = in[i * cols + j];
    }
}
