#include <arm_acle.h>
#include <arm_neon.h>

#define K_BLK 2048

static uint32_t crc_k1, crc_k2;
static int crc_init_done = 0;

static void crc_init_consts(void)
{
    uint32_t r = 0x80000000u;
    int e1 = 8 * K_BLK - 33;
    int e2 = 16 * K_BLK - 33;
    for (int i = 0; i < e2; i++) {
        if (i == e1) crc_k1 = r;
        r = (r >> 1) ^ ((r & 1) ? 0xEDB88320u : 0);
    }
    crc_k2 = r;
    crc_init_done = 1;
}

static inline uint64_t ld64(const uint8_t *p)
{
    uint64_t v;
    memcpy(&v, p, 8);
    return v;
}

static inline uint32_t shift_mul(uint32_t a, uint32_t k)
{
    poly128_t pr = vmull_p64((poly64_t)a, (poly64_t)k);
    uint64_t v = (uint64_t)pr;
    return __crc32d(0, v);
}

uint32_t crc32_ieee(const uint8_t *data, size_t n)
{
    uint32_t crc = 0xFFFFFFFFu;
    const uint8_t *p = data;

    if (n >= 3 * K_BLK) {
        if (!crc_init_done) crc_init_consts();
        const uint32_t k1 = crc_k1, k2 = crc_k2;
        while (n >= 3 * K_BLK) {
            uint32_t ca = crc, cb = 0, cc = 0;
            const uint8_t *pa = p, *pb = p + K_BLK, *pc = p + 2 * K_BLK;
            for (int i = 0; i < K_BLK / 8; i++) {
                uint64_t a = ld64(pa + 8 * i);
                uint64_t b = ld64(pb + 8 * i);
                uint64_t c = ld64(pc + 8 * i);
                ca = __crc32d(ca, a);
                cb = __crc32d(cb, b);
                cc = __crc32d(cc, c);
            }
            crc = shift_mul(ca, k2) ^ shift_mul(cb, k1) ^ cc;
            p += 3 * K_BLK;
            n -= 3 * K_BLK;
        }
    }
    while (n >= 8) {
        crc = __crc32d(crc, ld64(p));
        p += 8;
        n -= 8;
    }
    while (n > 0) {
        crc = __crc32b(crc, *p);
        p++;
        n--;
    }
    return ~crc;
}
