#include <arm_acle.h>

#define K_L_BYTES 2048
#define K_L_WORDS (K_L_BYTES / 8)

static uint32_t shift_tab[4][256];
static int shift_ready = 0;

static void init_shift(void)
{
    uint32_t basis[32];
    for (int i = 0; i < 32; i++) basis[i] = 1u << i;
    for (int s = 0; s < K_L_WORDS; s++)
        for (int i = 0; i < 32; i++)
            basis[i] = __crc32d(basis[i], 0);
    for (int k = 0; k < 4; k++) {
        shift_tab[k][0] = 0;
        for (int b = 1; b < 256; b++) {
            shift_tab[k][b] = shift_tab[k][b & (b - 1)] ^ basis[8 * k + __builtin_ctz(b)];
        }
    }
    shift_ready = 1;
}

static inline uint32_t apply_shift(uint32_t c)
{
    return shift_tab[0][c & 255] ^ shift_tab[1][(c >> 8) & 255] ^
           shift_tab[2][(c >> 16) & 255] ^ shift_tab[3][c >> 24];
}

static inline uint64_t ld64(const uint8_t *p)
{
    uint64_t v;
    memcpy(&v, p, 8);
    return v;
}

uint32_t crc32_ieee(const uint8_t *data, size_t n)
{
    uint32_t crc = 0xFFFFFFFFu;
    const uint8_t *p = data;

    /* align to 8 bytes */
    while (n && ((uintptr_t)p & 7)) {
        crc = __crc32b(crc, *p++);
        n--;
    }

    if (n >= 3 * K_L_BYTES) {
        if (!shift_ready) init_shift();
        while (n >= 3 * K_L_BYTES) {
            uint32_t c0 = crc, c1 = 0, c2 = 0;
            const uint8_t *p0 = p;
            const uint8_t *p1 = p + K_L_BYTES;
            const uint8_t *p2 = p + 2 * K_L_BYTES;
            for (int i = 0; i < K_L_WORDS; i++) {
                c0 = __crc32d(c0, ld64(p0 + 8 * i));
                c1 = __crc32d(c1, ld64(p1 + 8 * i));
                c2 = __crc32d(c2, ld64(p2 + 8 * i));
            }
            crc = apply_shift(apply_shift(c0)) ^ apply_shift(c1) ^ c2;
            p += 3 * K_L_BYTES;
            n -= 3 * K_L_BYTES;
        }
    }

    while (n >= 8) {
        crc = __crc32d(crc, ld64(p));
        p += 8;
        n -= 8;
    }
    while (n) {
        crc = __crc32b(crc, *p++);
        n--;
    }
    return ~crc;
}
