#include <arm_acle.h>

#define CRC_POLY 0xEDB88320u
#define BLK 1024u

static uint32_t crc_mulmodp(uint32_t a, uint32_t b) {
    uint32_t m = 1u << 31, p = 0;
    for (;;) {
        if (a & m) {
            p ^= b;
            if ((a & (m - 1)) == 0) break;
        }
        m >>= 1;
        b = (b & 1) ? (b >> 1) ^ CRC_POLY : b >> 1;
    }
    return p;
}

static uint32_t crc_x2n[32];

static uint32_t crc_x2nmodp(size_t n, unsigned k) {
    uint32_t p = 1u << 31;
    while (n) {
        if (n & 1) p = crc_mulmodp(crc_x2n[k & 31], p);
        n >>= 1;
        k++;
    }
    return p;
}

#ifdef __ARM_FEATURE_CRC32
static uint32_t crc_T1[4][256];
static uint32_t crc_T2[4][256];
static int crc_inited = 0;

static void crc_build(uint32_t T[4][256], uint32_t K) {
    uint32_t col[32];
    for (int j = 0; j < 32; j++) col[j] = crc_mulmodp(K, 1u << j);
    for (int k = 0; k < 4; k++) {
        T[k][0] = 0;
        for (int b = 1; b < 256; b++) {
            T[k][b] = T[k][b & (b - 1)] ^ col[8 * k + __builtin_ctz(b)];
        }
    }
}

static void crc_init(void) {
    uint32_t p = 1u << 30;
    for (int i = 0; i < 32; i++) {
        crc_x2n[i] = p;
        p = crc_mulmodp(p, p);
    }
    crc_build(crc_T1, crc_x2nmodp(BLK, 3));
    crc_build(crc_T2, crc_x2nmodp(2 * BLK, 3));
    crc_inited = 1;
}

static inline uint64_t ld64(const uint8_t *p) {
    uint64_t v;
    memcpy(&v, p, 8);
    return v;
}

uint32_t crc32_ieee(const uint8_t *data, size_t n) {
    if (!crc_inited) crc_init();
    uint32_t crc = 0xFFFFFFFFu;
    const uint8_t *p = data;

    while (n >= 3 * BLK) {
        uint32_t a = crc, b = 0, c = 0;
        const uint8_t *pb = p + BLK, *pc = p + 2 * BLK;
        for (unsigned i = 0; i < BLK; i += 8) {
            uint64_t x = ld64(p + i);
            uint64_t y = ld64(pb + i);
            uint64_t z = ld64(pc + i);
            a = __crc32d(a, x);
            b = __crc32d(b, y);
            c = __crc32d(c, z);
        }
        crc = c
            ^ crc_T2[0][a & 0xff] ^ crc_T2[1][(a >> 8) & 0xff]
            ^ crc_T2[2][(a >> 16) & 0xff] ^ crc_T2[3][a >> 24]
            ^ crc_T1[0][b & 0xff] ^ crc_T1[1][(b >> 8) & 0xff]
            ^ crc_T1[2][(b >> 16) & 0xff] ^ crc_T1[3][b >> 24];
        p += 3 * BLK;
        n -= 3 * BLK;
    }
    while (n >= 8) {
        crc = __crc32d(crc, ld64(p));
        p += 8;
        n -= 8;
    }
    while (n--) {
        crc = __crc32b(crc, *p++);
    }
    return crc ^ 0xFFFFFFFFu;
}
#else
static uint32_t crc_tab[256];
static int crc_inited = 0;

uint32_t crc32_ieee(const uint8_t *data, size_t n) {
    if (!crc_inited) {
        for (uint32_t i = 0; i < 256; i++) {
            uint32_t c = i;
            for (int k = 0; k < 8; k++) c = (c & 1) ? (c >> 1) ^ CRC_POLY : c >> 1;
            crc_tab[i] = c;
        }
        crc_inited = 1;
    }
    uint32_t crc = 0xFFFFFFFFu;
    for (size_t i = 0; i < n; i++)
        crc = crc_tab[(crc ^ data[i]) & 0xff] ^ (crc >> 8);
    return crc ^ 0xFFFFFFFFu;
}
