```c
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

static inline __attribute__((always_inline)) void lv_step(uint64_t *pv, uint64_t *mv,
        uint64_t eq, uint64_t hp, uint64_t hm, int lb, uint64_t *hpo, uint64_t *hmo)
{
    uint64_t Pv = *pv, Mv = *mv;
    uint64_t Xv = eq | Mv;
    eq |= hm;
    uint64_t Xh = (((eq & Pv) + Pv) ^ Pv) | eq;
    uint64_t Ph = Mv | ~(Xh | Pv);
    uint64_t Mh = Pv & Xh;
    *hpo = (Ph >> lb) & 1;
    *hmo = (Mh >> lb) & 1;
    Ph = (Ph << 1) | hp;
    Mh = (Mh << 1) | hm;
    *pv = Mh | ~(Xv | Ph);
    *mv = Ph & Xv;
}

static size_t lv_slow(const char *s, size_t n, const char *t, size_t m)
{
    size_t *row = malloc((m + 1) * sizeof(size_t));
    if (!row) return 0;
    for (size_t j = 0; j <= m; j++) row[j] = j;
    for (size_t i = 1; i <= n; i++) {
        size_t diag = row[0];
        row[0] = i;
        for (size_t j = 1; j <= m; j++) {
            size_t up = row[j];
            size_t v = diag + (s[i - 1] != t[j - 1]);
            if (row[j] + 1 < v) v = row[j] + 1;
            if (row[j - 1] + 1 < v) v = row[j - 1] + 1;
            diag = up;
            row[j] = v;
        }
    }
    size_t r = row[m];
    free(row);
    return r;
}

size_t levenshtein(const char *s, size_t n, const char *t, size_t m)
{
    if (n == 0) return m;
    if (m == 0) return n;

    for (size_t i = 0; i < n; i++)
        if ((unsigned char)(s[i] - 'a') > 3) return lv_slow(s, n, t, m);
    for (size_t j = 0; j < m; j++)
        if ((unsigned char)(t[j] - 'a') > 3) return lv_slow(s, n, t, m);

    size_t nb = (n + 63) / 64;
    uint64_t *buf = calloc(4 * nb + 2 * nb, sizeof(uint64_t));
    if (!buf) return lv_slow(s, n, t, m);
    uint64_t *peq = buf;
    uint64_t *P = buf + 4 * nb;
    uint64_t *M = P + nb;

    for (size_t i = 0; i < n; i++) {
        unsigned c = (unsigned char)s[i] & 3;
        peq[c * nb + (i >> 6)] |= 1ULL << (i & 63);
    }
    for (size_t b = 0; b < nb; b++) { P[b] = ~0ULL; M[b] = 0; }

    int lastbit = (int)((n - 1) & 63);
    long score = (long)n;

    for (size_t j = 0; j < m; j++) {
        const uint64_t *eq = peq + ((unsigned)(unsigned char)t[j] & 3) * nb;
        uint64_t hp = 1, hm = 0, hpo, hmo;
        for (size_t b = 0; b + 1 < nb; b++) {
            lv_step(&P[b], &M[b], eq[b], hp, hm, 63, &hpo, &hmo);
            hp = hpo; hm = hmo;
        }
        lv_step(&P[nb - 1], &M[nb - 1], eq[nb - 1], hp, hm, lastbit, &hpo, &hmo);
        score += (long)hpo - (long)hmo;
    }
    free(buf);
    return (size_t)score;
}
```
