#include <stdint.h>
#include <stdlib.h>
#include <string.h>

size_t levenshtein(const char *s, size_t n, const char *t, size_t m)
{
    if (n == 0) return m;
    if (m == 0) return n;

    size_t W = (n + 63) / 64;
    int symmap[256];
    for (int i = 0; i < 256; i++) symmap[i] = -1;
    int nsym = 0;
    for (size_t i = 0; i < n; i++) {
        unsigned char c = (unsigned char)s[i];
        if (symmap[c] < 0) symmap[c] = nsym++;
    }
    /* row nsym is the all-zero row */
    uint64_t *peq = (uint64_t *)calloc((size_t)(nsym + 1) * W, sizeof(uint64_t));
    uint64_t *Pvs = (uint64_t *)malloc(W * sizeof(uint64_t));
    uint64_t *Mvs = (uint64_t *)malloc(W * sizeof(uint64_t));
    if (!peq || !Pvs || !Mvs) {
        free(peq); free(Pvs); free(Mvs);
        return (size_t)-1;
    }
    for (size_t i = 0; i < n; i++) {
        int k = symmap[(unsigned char)s[i]];
        peq[(size_t)k * W + (i >> 6)] |= 1ULL << (i & 63);
    }
    for (size_t b = 0; b < W; b++) { Pvs[b] = ~0ULL; Mvs[b] = 0; }
    for (int i = 0; i < 256; i++) if (symmap[i] < 0) symmap[i] = nsym;

    const uint64_t HIGH = 1ULL << 63;
    const uint64_t LAST = 1ULL << ((n - 1) & 63);
    long score = (long)n;

    for (size_t j = 0; j < m; j++) {
        const uint64_t *row = peq + (size_t)symmap[(unsigned char)t[j]] * W;
