            uint64_t Pv = Pvs[b], Mv = Mvs[b], Eq = row[b];
            uint64_t Xv = Eq | Mv;
            if (hin < 0) Eq |= 1;
            uint64_t Xh = (((Eq & Pv) + Pv) ^ Pv) | Eq;
            uint64_t Ph = Mv | ~(Xh | Pv);
            uint64_t Mh = Pv & Xh;
            uint64_t hm = (b == W - 1) ? LAST : HIGH;
            int hout = 0;
