        unsigned c = (unsigned char)s[i];
        peq[c * W + (i >> 6)] |= (uint64_t)1 << (i & 63);
    }
    for (size_t b = 0; b < W; b++) {
        Pv[b] = ~(uint64_t)0;
        Mv[b] = 0;
    }

    const uint64_t HIGH = (uint64_t)1 << 63;
    uint64_t lastbit = (uint64_t)1 << ((n - 1) & 63);
    long score = (long)n;

    for (size_t j = 0; j < m; j++) {
        const uint64_t *eqrow = peq + (size_t)(unsigned char)t[j] * W;
        int hin = 1;
        for (size_t b = 0; b < W; b++) {
            uint64_t hb = (b == W - 1) ? lastbit : HIGH;
            uint64_t pv = Pv[b], mv = Mv[b];
            uint64_t eq = eqrow[b];
            uint64_t xv = eq | mv;
            if (hin < 0) eq |= 1;
            uint64_t xh = (((eq & pv) + pv) ^ pv) | eq;
            uint64_t ph = mv | ~(xh | pv);
            uint64_t mh = pv & xh;
            int hout = 0;
            if (ph & hb) hout = 1;
            else if (mh & hb) hout = -1;
            ph <<= 1;
            mh <<= 1;
            if (hin < 0) mh |= 1;
            else if (hin > 0) ph |= 1;
            Pv[b] = mh | ~(xv | ph);
            Mv[b] = ph & xv;
            if (b == W - 1) {
                score += hout;
            } else {
                /* carry uses top bit of the full word */
                hin = hout;
            }
        }
    }

    free(peq);
    return (size_t)score;
}
