#include <arm_neon.h>

static inline __attribute__((always_inline))
void k0_build(const uint8_t *p, uint64_t *out)
{
    static const uint8_t wt[16] = {1,2,4,8,16,32,64,128,1,2,4,8,16,32,64,128};
    const uint8x16_t w = vld1q_u8(wt);
    const uint8x16_t one = vdupq_n_u8(1);
    const uint8x16_t two = vdupq_n_u8(2);
    uint8x16_t v0 = vld1q_u8(p);
    uint8x16_t v1 = vld1q_u8(p + 16);
    uint8x16_t v2 = vld1q_u8(p + 32);
    uint8x16_t v3 = vld1q_u8(p + 48);

    uint8x16_t a0 = vandq_u8(vtstq_u8(v0, one), w);
    uint8x16_t a1 = vandq_u8(vtstq_u8(v1, one), w);
    uint8x16_t a2 = vandq_u8(vtstq_u8(v2, one), w);
    uint8x16_t a3 = vandq_u8(vtstq_u8(v3, one), w);
    uint8x16_t t0 = vpaddq_u8(a0, a1);
    uint8x16_t t1 = vpaddq_u8(a2, a3);
    uint8x16_t u = vpaddq_u8(t0, t1);
    u = vpaddq_u8(u, u);
    uint64_t P0 = vgetq_lane_u64(vreinterpretq_u64_u8(u), 0);

    uint8x16_t b0 = vandq_u8(vtstq_u8(v0, two), w);
    uint8x16_t b1 = vandq_u8(vtstq_u8(v1, two), w);
    uint8x16_t b2 = vandq_u8(vtstq_u8(v2, two), w);
    uint8x16_t b3 = vandq_u8(vtstq_u8(v3, two), w);
    t0 = vpaddq_u8(b0, b1);
    t1 = vpaddq_u8(b2, b3);
    u = vpaddq_u8(t0, t1);
    u = vpaddq_u8(u, u);
    uint64_t P1 = vgetq_lane_u64(vreinterpretq_u64_u8(u), 0);

    out[1] = P0 & ~P1;
    out[2] = P1 & ~P0;
    out[3] = P0 & P1;
    out[0] = ~(P0 | P1);
}

static inline __attribute__((always_inline))
uint64_t k0_block(const uint64_t *cur, const uint64_t *nxt, const uint8_t *pid, size_t m)
{
    uint64_t acc = ~0ULL;
#pragma GCC unroll 16
    for (size_t j = 0; j < m; j++) {
        unsigned id = pid[j];
        uint64_t c = cur[id], x = nxt[id];
        uint64_t s = j ? ((c >> j) | (x << (64 - j))) : c;
        acc &= s;
    }
    return acc;
}

static inline __attribute__((always_inline))
uint64_t k0_core(const uint8_t *text, size_t K, const uint8_t *pid, size_t m)
{
    uint64_t A[4], B[4];
    uint64_t total = 0;
    k0_build(text, A);
    size_t k = 0;
    for (; k + 1 < K; k += 2) {
        k0_build(text + 64 * (k + 1), B);
        total += (uint64_t)__builtin_popcountll(k0_block(A, B, pid, m));
        k0_build(text + 64 * (k + 2), A);
        total += (uint64_t)__builtin_popcountll(k0_block(B, A, pid, m));
    }
    if (k < K) {
        k0_build(text + 64 * (k + 1), B);
        total += (uint64_t)__builtin_popcountll(k0_block(A, B, pid, m));
    }
    return total;
}

uint64_t count_substr(const char *text, size_t n, const char *pat, size_t m)
{
    if (m > n || m == 0) return 0;
    const uint8_t *t = (const uint8_t *)text;
    uint8_t pid[64];
    for (size_t j = 0; j < m; j++) pid[j] = (uint8_t)(((const uint8_t *)pat)[j] & 3);

    size_t nb = n / 64;
    size_t K = nb ? nb - 1 : 0;
    uint64_t total = 0;
    if (K > 0) {
        if (m == 12)
            total = k0_core(t, K, pid, 12);
        else
            total = k0_core(t, K, pid, m);
    }
    for (size_t i = 64 * K; i + m <= n; i++) {
        if (memcmp(text + i, pat, m) == 0) total++;
    }
    return total;
}
